import{_ as l,o as r,c as n,j as e,a}from"./chunks/framework.CAXxHpAX.js";const f=JSON.parse('{"title":"中论丹道-养气忘言守","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/中论丹道-养气忘言守.md","filePath":"60-原文段落/中论丹道-养气忘言守.md","lastUpdated":1778155802000}'),o={name:"60-原文段落/中论丹道-养气忘言守.md"};function s(_,t,c,d,p,i){return r(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"中论丹道-养气忘言守",tabindex:"-1"},[a("中论丹道-养气忘言守 "),e("a",{class:"header-anchor",href:"#中论丹道-养气忘言守","aria-label":'Permalink to "中论丹道-养气忘言守"'},"​")],-1),e("blockquote",null,[e("p",null,[a("来源："),e("a",{href:"/01-Raw-Sources/中论丹道_了空居士_完整版(全83篇)"},"中论丹道_了空居士_完整版(全83篇)"),a(" 切分日期：2026-05-06")])],-1),e("hr",null,null,-1),e("p",null,[e("strong",null,"【原文】养气忘言守，降心为不为")],-1),e("p",null,'养气，养我们体内的能量。我常常喜欢说，孟子说"吾善养吾浩然正气""充塞天地"，当你大开顶之后，进入还虚合道之后，你就真的知道你的浩然之气会充塞天下，医家说天人合一，道家说炼虚合道，老子《道德经》说"有物混成"，或者是"恍兮惚兮，其中有象…有物"等等，你就会明白。所以"养气忘言守"，真正要修炼，修炼的过程可以认为就是养气的过程，养浩然之气的过程。那怎么养呢？要"忘言守"。"忘言"，就是少说废话，甚至是不说废话；"守"呢？不要特别去意守丹田，你说，师父你不是叫我们守手指脚趾吗？不是的！我们每个人正常的心态就是轻轻知道手脚的位置，不然走路不小心会摔跤，拿东西不小心会掉下，正常的心态就是你的心会知道你的手脚的一切动作，知道你的嘴巴要说话，有些人为什么会脱口而出说错话，还说是有口无心呢，其实是他的精神不够饱满，大脑开小差，他脱口而出是潜意识在作怪，他显意识不知道，我们正常人显意识和潜意识要一致，功夫高深的人更是显意识和潜意识可以说绝对一致的，所以说功夫高深的人定慧等持，他不会做错事，也不会说错话，所以说"忘言守"，不要去意守丹田，还有没有守别的？不要去守体外的东西。你说师父啊，谁在守体外的东西啊？你们平时在想东想西，患得患失，你在想着不就是守吗？所以"养气忘言守"，就是少说废话，也不要胡思乱想，一定要心平气和，这才是真正的修炼功法。',-1)])])}const m=l(o,[["render",s]]);export{f as __pageData,m as default};
